import argparse, csv, hashlib
from pathlib import Path

ap=argparse.ArgumentParser(); ap.add_argument("--phase3-dir",required=True); a=ap.parse_args()
p=Path(a.phase3_dir).expanduser().resolve(); report=p/"PHASE3_COMPLETION_REPORT.md"
if "test" in str(p).lower() or p.name!="Phase_3" or not p.is_dir(): raise ValueError("Refusing test path; use an existing Phase_3 directory")
if report.exists(): raise FileExistsError("Refusing to overwrite "+str(report))
def digest(x):
 h=hashlib.sha256()
 with x.open("rb") as f:
  for b in iter(lambda:f.read(1<<20),b""): h.update(b)
 return h.hexdigest()
def rows(x):
 if not x.is_file(): return []
 with x.open(encoding="utf-8-sig",newline="") as f: return list(csv.DictReader(line for line in f if not line.lstrip().startswith("#")))
def files(pattern):
 return sorted(x for x in p.glob(pattern) if x.is_file() and "test" not in x.name.lower())
demo,voice,lat=rows(p/"demo_log.csv"),rows(p/"voice_log.csv"),rows(p/"latency_log.csv")
conds={c:sum(str(r.get("condition (slow/fast/noisy)","")).strip().lower()==c for r in voice) for c in ("slow","fast","noisy")}
matches=sum(str(r.get("transcript_matches (Y/N)","")).strip().upper()=="Y" for r in voice); changed=sum(str(r.get("asr_changed_meaning (Y/N)","")).strip().upper()=="Y" for r in voice)
print("voice_runs",len(voice),"conditions",conds,"transcript_matches_Y",matches,"asr_meaning_changes_Y",changed); print("demo_rows",len(demo),"empty_actual_label",sum(not str(r.get("actual_label","")).strip() for r in demo))
if len(voice)<10: print("WARNING: fewer than 10 voice runs")
screens=files("p3_*.png"); dropdown=files("p3_dropdown_*.png"); cases_shots=files("p3_five_cases_*.png"); voice_shots=files("p3_voice_run_*.png"); review_shots=files("p3_review_output_*.png"); fresh=files("phase3_fresh_runtime_check_*.log"); video=p/"p3_backup_demo.mp4"
demo5=len(demo)==5 and len({str(r.get("case_id","")).strip() for r in demo})==5 and all(str(r.get("actual_label","")).strip() for r in demo)
outputs=demo5 and all(all(str(r.get(k,"")).strip() for k in ("score_out_of_2","confidence","review_flag")) for r in demo)
voice10=len(voice)==10 and conds=={"slow":4,"fast":3,"noisy":3}; trans=voice10 and all(all(str(r.get(k,"")).strip() for k in ("transcript","transcript_matches (Y/N)","asr_changed_meaning (Y/N)")) for r in voice)
lat_ok=any(str(r.get("block","")).strip().lower() in ("block 62","62","cell 163") and str(r.get("run_label","")).strip().lower()=="batch-1" for r in lat) and any(str(r.get("block","")).strip().lower() in ("block 62","62","cell 163") and str(r.get("run_label","")).strip().lower()=="batch-15" for r in lat)
items=[("dropdown tested",bool(dropdown),dropdown),("five cases tested",demo5,[p/"demo_log.csv"]), ("voice test (10)",voice10,[p/"voice_log.csv"]), ("transcription failures recorded",trans,[p/"voice_log.csv"]), ("score/confidence/review inspected",outputs,[p/"demo_log.csv"]), ("fresh-runtime A_predict run",any(x.stat().st_size>0 for x in fresh),fresh), ("Block 62 latency",lat_ok,[p/"latency_log.csv"]), ("screenshots",bool(dropdown and cases_shots and voice_shots and review_shots),screens), ("backup video",video.is_file() and video.stat().st_size>0,[video] if video.is_file() else [])]
lines=["# Phase 3 completion evidence check","","Generated by the local read-only checker. This report does not contain its own hash.",""]
for name,ok,paths in items:
 lines += [f"- {'DONE' if ok else 'MISSING'} — {name}"]
 for x in paths: lines.append(f"  - {x.name} | SHA-256 {digest(x)}" if x.is_file() else f"  - {x.name} | missing")
with report.open("x",encoding="utf-8") as f: f.write("\n".join(lines)+"\n")
print("report",report)
